// Sliding window maximum - monotoniczna kolejka indeksow
int[] nums = {1, 3, -1, -3, 5, 3, 6, 7};
int k = 3;
Deque<Integer> window = new ArrayDeque<>();
for (int i = 0; i < nums.length; i++) {
    while (!window.isEmpty() && window.peekFirst() < i - k + 1)
        window.pollFirst(); // usun indeksy spoza okna
    while (!window.isEmpty() && nums[window.peekLast()] < nums[i])
        window.pollLast();  // usun mniejsze wartosci z konca
    window.offerLast(i);
    if (i >= k - 1)
        System.out.print(nums[window.peekFirst()] + " ");
}

