static boolean isPalindrome(String s) {
    Deque<Character> chars = new ArrayDeque<>();
    for (char c : s.toCharArray()) chars.addLast(c);

    while (chars.size() > 1) {
        if (!chars.pollFirst().equals(chars.pollLast())) {
            return false;
        }
    }
    return true;
}

public static void main(String[] args) {
    System.out.println("kajak: " + isPalindrome("kajak"));
    System.out.println("hello: " + isPalindrome("hello"));
}

