static int evaluatePostfix(String expression) {
    Deque<Integer> stack = new ArrayDeque<>();
    for (String token : expression.split(" ")) {
        switch (token) {
            case "+", "-", "*", "/" -> {
                int b = stack.pop();
                int a = stack.pop();
                int result = switch (token) {
                    case "+" -> a + b;
                    case "-" -> a - b;
                    case "*" -> a * b;
                    default -> a / b;
                };
                stack.push(result);
            }
            default -> stack.push(Integer.parseInt(token));
        }
    }
    return stack.pop();
}

public static void main(String[] args) {
    System.out.println(evaluatePostfix("5 3 + 2 *"));
}

class DequeLRUCache {
    private final int capacity;
    private final Deque<Integer> order = new ArrayDeque<>();
    private final Set<Integer> present = new HashSet<>();

    DequeLRUCache(int capacity) { this.capacity = capacity; }

    void access(int key) {
        if (present.contains(key)) {
            order.remove((Integer) key);
        } else if (present.size() >= capacity) {
            int evicted = order.removeLast();
            present.remove(evicted);
        }
        order.addFirst(key);
        present.add(key);
    }

    public String toString() { return order.toString(); }
}

