static boolean isValidExpression(String s) {
    Deque<Integer> stack = new ArrayDeque<>(); // pozycje otwierajacych nawiasow
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            stack.push(i);
        } else if (c == ')') {
            if (stack.isEmpty()) return false;
            int openPos = stack.pop();
            if (openPos == i - 1) return false; // pusta para "()"
        }
    }
    return stack.isEmpty();
}

public static void main(String[] args) {
    System.out.println(isValidExpression("(1+2)*(3-4)"));
    System.out.println(isValidExpression("()"));
    System.out.println(isValidExpression("(1+(2*3)"));
}

Map<Integer, List<Integer>> graph = Map.of(
    1, List.of(2, 3), 2, List.of(4), 3, List.of(4), 4, List.of()
);

Queue<Integer> queue = new ArrayDeque<>();
Set<Integer> visited = new HashSet<>();
List<Integer> order = new ArrayList<>();

queue.offer(1);
visited.add(1);

while (!queue.isEmpty()) {
    int node = queue.poll();
    order.add(node);
    for (int neighbor : graph.getOrDefault(node, List.of())) {
        if (visited.add(neighbor)) {
            queue.offer(neighbor);
        }
    }
}
System.out.println("Kolejnosc BFS: " + order);
